<script setup lang="ts">
import {computed} from 'vue';import {stats,type Pattern} from './engine';import {printBlocks} from './materials';
const props=defineProps<{pattern:Pattern,size:number}>();defineEmits<{close:[]}>();
const blocks=computed(()=>printBlocks(props.pattern,props.size));const counts=computed(()=>stats(props.pattern.cells));const color=(c:string|null)=>props.pattern.palette.find(v=>v.code===c)?.hex??'#fff';
const foreground=(hex:string)=>parseInt(hex.slice(1,3),16)*.299+parseInt(hex.slice(3,5),16)*.587+parseInt(hex.slice(5),16)*.114>145?'#111':'#fff';
function print(){window.print()}
</script>
<template><div class="print-view"><div class="no-print"><button @click="print">打印 / 保存 PDF</button><button @click="$emit('close')">关闭</button><p>按格制作；屏幕尺寸不代表打印比例。</p></div><section class="print-page"><h2>图纸总览</h2><p>{{pattern.width}} × {{pattern.height}} · {{counts.total}} 颗 · {{blocks.length}} 块</p><svg :viewBox="`0 0 ${pattern.width} ${pattern.height}`" class="print-overview"><rect v-for="(c,i) in pattern.cells" :x="i%pattern.width" :y="Math.floor(i/pattern.width)" width="1" height="1" :fill="color(c)"/><g v-for="(b,i) in blocks"><rect :x="b.x" :y="b.y" :width="b.width" :height="b.height" fill="none" stroke="black" stroke-width=".3"/><text :x="b.x+1" :y="b.y+4" font-size="3">{{i+1}}</text></g></svg><div class="print-legend"><span v-for="c in pattern.palette.filter(c=>counts.counts[c.code])">{{c.code}} · {{counts.counts[c.code]}} 颗</span></div></section><section v-for="(b,index) in blocks" class="print-page"><h2>第 {{index+1}} / {{blocks.length}} 块</h2><p>行 {{b.y+1}}–{{b.y+b.height}} · 列 {{b.x+1}}–{{b.x+b.width}}</p><svg :viewBox="`-1 -1 ${b.width+2} ${b.height+2}`" class="print-block"><template v-for="row in b.height"><g v-for="col in b.width"><rect :x="col-1" :y="row-1" width="1" height="1" :fill="color(pattern.cells[(b.y+row-1)*pattern.width+b.x+col-1])" stroke="#888" stroke-width=".025"/><text v-if="pattern.cells[(b.y+row-1)*pattern.width+b.x+col-1]" :x="col-.5" :y="row-.35" font-size=".25" text-anchor="middle" :fill="foreground(color(pattern.cells[(b.y+row-1)*pattern.width+b.x+col-1]))">{{pattern.cells[(b.y+row-1)*pattern.width+b.x+col-1]}}</text></g></template></svg></section></div></template>
<style scoped>.print-view{position:fixed;inset:0;background:white;z-index:20;overflow:auto;padding:24px}.print-page{max-width:800px;margin:20px auto;break-after:page}.print-block{width:100%;max-height:230mm}.print-overview{height:360px;max-width:100%}.print-legend{display:flex;flex-wrap:wrap;gap:15px}@media print{.no-print{display:none}.print-view{position:static;overflow:visible;padding:0}.print-page{margin:0;page-break-after:always}} </style>
